CREATE TABLE bank_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),clinic_id uuid NOT NULL REFERENCES clinics(id),name text NOT NULL,account_reference text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),UNIQUE(id,clinic_id));
CREATE TABLE bank_statement_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bank_account_id uuid NOT NULL,clinic_id uuid NOT NULL,reference text NOT NULL,booked_on date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor<>0),journal_line_id uuid UNIQUE REFERENCES journal_lines(id),matched_by uuid REFERENCES users(id),matched_at timestamptz,UNIQUE(bank_account_id,reference),FOREIGN KEY(bank_account_id,clinic_id) REFERENCES bank_accounts(id,clinic_id));
